dtsPropsFor.Lienzo:
/** Render prop: recibe el ancho y alto ya medidos del contenedor. Todas las primitivas
 *  SVG piden w y h explicitos, y este es el unico componente que los mide. */
children: (medida: { w: number; h: number }) => React.ReactNode;
className?: string;

dtsPropsFor.Plaqueta:
/** Va DENTRO de un <svg>: devuelve un <g>, no un svg propio. */
x: number;
y: number;
texto: string;
fuente?: number;
peso?: number;
color?: string;
anclaje?: 'start' | 'middle' | 'end';
padX?: number;

dtsPropsFor.ReferenciaV:
/** Va DENTRO de un <svg>: devuelve un <g>, no un svg propio. */
x: number;
h: number;
etiqueta?: string;
y?: number;

dtsPropsFor.BarrasH:
datos: Array<{ etiqueta: string; valor: number; nota?: string; sufijo?: string; enfasis?: boolean; excepcion?: boolean }>;
w: number;
h: number;
formato?: (v: number) => string;
formatoEje?: (v: number) => string;
tituloEje?: string;
anchoEtiqueta?: number;
onBarra?: (i: number, d: unknown) => void;
referencia?: { valor: number; etiqueta?: string };
tope?: number;

dtsPropsFor.Linea:
/** `valor: null` deja un hueco: el tramo no se dibuja y NO se interpola. */
serie: Array<{ etiqueta: string; valor: number | null }>;
w: number;
h: number;
formato?: (v: number) => string;
/** Banda de meta, [minimo, maximo]. */
banda?: [number, number];
/** Segunda banda, tipicamente la linea base historica. */
banda2?: [number, number];
/** Franjas de estado sobre el eje Y: la posicion de la linea ES el estado. */
zonas?: Array<{ etiqueta: string; desde: number; hasta: number; tono: string; rango?: string; activa?: boolean }>;
rotuloBanda?: string;
rotuloBanda2?: string;
tituloEje?: string;
tituloY?: string;

dtsPropsFor.PuntosIC:
/** Una fila por criterio. `vacio` reserva el renglon sin dibujar punto: es como se
 *  declara un score que todavia no existe. `tenue` baja la fila a contexto. */
datos: Array<{ etiqueta: string; valor?: number; ic?: [number, number]; nota?: string; enfasis?: boolean; tenue?: boolean; vacio?: boolean; excepcion?: boolean }>;
w: number;
h: number;
formato?: (v: number) => string;
tituloEje?: string;
anchoEtiqueta?: number;
/** Vara punteada, con su propio intervalo. */
referencia?: { valor: number; ic?: [number, number]; rotulo?: string };

dtsPropsFor.BarraTramos:
/** Barra unica partida en tramos que suman el total. Se normaliza contra su propio
 *  total, asi que dos BarraTramos con bases distintas miden lo mismo en pantalla:
 *  la base va escrita al lado, no dibujada. */
tramos: Array<{ etiqueta: string; valor: number; enfasis?: boolean }>;
w: number;
h: number;
formato?: (v: number) => string;
banda?: [number, number];
alturaBarra?: number;

dtsPropsFor.BarrasApiladas100:
/** Una barra por fila, escala fija de 0 a 100 por ciento. `sub` declara la base de esa
 *  fila. Los tonos 'trama' y 'trama-exc' resuelven a patrones (ver Tramas). */
filas: Array<{ etiqueta: string; sub?: string | null; nota?: string; enfasis?: boolean; segmentos: Array<{ clave: string; valor: number; tono: string; tinta?: string; enfasis?: boolean; plaqueta?: boolean; texto?: string | null; idx?: number }> }>;
w: number;
h: number;
anchoEtiqueta?: number;
tituloEje?: string;
encabezadoNota?: string;
leyenda?: Array<{ etiqueta: string; tono: string; enfasis?: boolean }>;
/** Une los cortes de filas consecutivas: la inclinacion ES la diferencia. */
conectores?: boolean;
alturaBarra?: number;
referencia?: { valor: number; etiqueta?: string };
onFila?: (i: number) => void;
onSegmento?: (s: unknown) => void;
/** Texto de los tramos sin lugar para su rotulo, que bajan a la linea de resto. */
textoResto?: (it: unknown) => string;
rotuloResto?: string;

dtsPropsFor.BarrasDivergentes:
/** Barras alrededor de cero, ordenadas por valor. `nota` es la columna de la derecha;
 *  `notaValor` le agrega su propia barra. */
datos: Array<{ etiqueta: string; valor: number; nota?: string; notaValor?: number; notaSuf?: string | null; enfasis?: boolean }>;
w: number;
h: number;
formato?: (v: number) => string;
formatoEje?: (v: number) => string;
tituloEje?: string;
anchoEtiqueta?: number;
minimoEje?: number;
encabezadoNota?: string;
rotuloPos?: string;
rotuloNeg?: string;
onBarra?: (i: number, d: unknown) => void;

dtsPropsFor.Chispa:
/** Sparkline. La serie son valores crudos, sin etiquetas. */
serie: number[];
w: number;
h: number;
banda?: [number, number];
tonoBanda?: string;
rotulo?: string;
rotuloBanda?: string;

dtsPropsFor.BarraMini:
/** Una parte sobre un total, para la prueba grafica de una tarjeta. */
parte: number;
total: number;
w: number;
h?: number;
alturaBarra?: number;
/** Pinta la parte como excepcion (terracota) en vez de enfasis (azul). */
excepcion?: boolean;
rotulo?: string | null;
pie?: string | null;

dtsPropsFor.CurvaConcentracion:
/** Curva de cobertura acumulada. `acum` viene ya ordenado de mayor a menor aporte. */
acum: number[];
total: number;
nRiesgo: number;
/** Los dos cortes declarados de capacidad, marcados sobre la curva. */
capLo: number;
capHi: number;
w: number;
h: number;
kFijado?: number | null;
kHover?: number | null;
onHover?: (k: number | null) => void;
onFijar?: (k: number) => void;
formatoPct?: (v: number) => string;
tituloX?: string;
tituloY?: string;

dtsPropsFor.SerieCortes:
/** Serie chica de los cortes, con el activo marcado por indice. */
valores: number[];
activo: number;
w: number;
h: number;

dtsPropsFor.Semaforo:
/** Cada estado cambia de FORMA ademas de color: se lee impreso en blanco y negro.
 *  Los 'inv-*' son los mismos tres estados con rotulo invertido, para indicadores
 *  donde mas alto es peor (ver estadoInverso). */
estado: 'meta' | 'cerca' | 'fuera' | 'inv-meta' | 'inv-cerca' | 'inv-fuera';
sufijo?: string;
/** Nombra el indicador: una pastilla suelta que dice "Fuera de meta" no dice de que. */
de?: string;
contra?: string;
tamano?: 'chico' | 'grande';

dtsPropsFor.Region:
/** Se derraman sobre el <svg> raiz, pisando los defaults (12x12, viewBox 0 0 16 16,
 *  stroke currentColor de 1.4 a 1.5, aria-hidden). */
width?: number | string;
height?: number | string;
className?: string;
style?: React.CSSProperties;
color?: string;
[key: string]: unknown;

